CREATE OR REPLACE FUNCTION public.claim_chat_media_view(p_message_id uuid, p_request_id uuid)
 RETURNS TABLE(url text, remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE m public.messages%ROWTYPE; g public.chat_media_view_grants%ROWTYPE; v integer;
BEGIN
 IF auth.uid() IS NULL OR p_request_id IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
 -- Serialize grants for this message; no two devices can consume the last view.
 SELECT * INTO m FROM public.messages WHERE id = p_message_id FOR UPDATE;
 IF m.id IS NULL OR m.deleted_at IS NOT NULL OR m.view_limit IS NULL OR public.can_act_as(m.sender_id)
   OR NOT public.can_access_chat_conversation(m.conversation_id)
   OR public.chat_object_path(m.media_url) IS NULL
   OR split_part(public.chat_object_path(m.media_url), '/', 2) <> m.sender_id::text THEN
   RETURN QUERY SELECT NULL::text, 0; RETURN;
 END IF;
 SELECT * INTO g FROM public.chat_media_view_grants WHERE user_id = auth.uid() AND request_id = p_request_id;
 IF FOUND THEN
   IF g.message_id = p_message_id AND g.expires_at > now() THEN RETURN QUERY SELECT m.media_url, g.remaining;
   ELSE RETURN QUERY SELECT NULL::text, 0; END IF;
   RETURN;
 END IF;
 INSERT INTO public.message_views(message_id,user_id,views,first_viewed_at)
 VALUES(m.id,auth.uid(),0,now()) ON CONFLICT DO NOTHING;
 SELECT views INTO v FROM public.message_views WHERE message_id=m.id AND user_id=auth.uid() FOR UPDATE;
 IF v >= m.view_limit THEN RETURN QUERY SELECT NULL::text,0; RETURN; END IF;
 UPDATE public.message_views SET views=views+1, first_viewed_at=coalesce(first_viewed_at,now()) WHERE message_id=m.id AND user_id=auth.uid();
 INSERT INTO public.chat_media_view_grants(request_id,user_id,message_id,remaining) VALUES(p_request_id,auth.uid(),m.id,m.view_limit-v-1);
 RETURN QUERY SELECT m.media_url, m.view_limit-v-1;
END;
$function$

CREATE OR REPLACE FUNCTION public.content_media_document(p_kind text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_document jsonb; v_article public.articles; v_blocks jsonb;
begin
  if p_kind = 'post' then
    select jsonb_build_object('media_url', p.media_url, 'image_url', p.image_url,
      'media', coalesce((select jsonb_agg(jsonb_build_object('url', m.url, 'edit', m.edit)) from public.post_media m where m.post_id = p.id), '[]'::jsonb),
      'products', coalesce((select jsonb_agg(jsonb_build_object('image_url', pp.image_url)) from public.post_products pp where pp.post_id = p.id), '[]'::jsonb))
      into v_document from public.posts p where p.id = p_id;
    select * into v_article from public.articles a where a.linked_post_id = p_id limit 1;
    if found then
      select coalesce(jsonb_agg(b.content), '[]'::jsonb) into v_blocks from public.article_blocks b where b.revision_id = v_article.current_revision_id;
      v_document := v_document || jsonb_build_object('article', v_blocks, 'assets', (
        select coalesce(jsonb_agg(jsonb_build_object('url', a.url, 'thumbnail_url', a.thumbnail_url)), '[]'::jsonb)
        from public.media_assets a where a.id = v_article.cover_asset_id or a.id::text in (select public.content_media_strings(v_blocks))
      ));
    end if;
  elsif p_kind = 'story' then
    select jsonb_build_object('media_url', s.media_url, 'thumbnail_url', s.thumbnail_url, 'dual_front_url', s.dual_front_url,
      'audio_url', s.audio_url, 'media_transform', s.media_transform,
      'stickers', coalesce((select jsonb_agg(jsonb_build_object('photoUrl', sticker->>'photoUrl'))
        from jsonb_array_elements(case when jsonb_typeof(s.stickers_json) = 'array' then s.stickers_json else '[]'::jsonb end) sticker), '[]'::jsonb))
      into v_document from public.stories s where s.id = p_id;
    -- postMediaUrl/entityImage are deliberately excluded. Their source content
    -- needs its own current authorization; a public outer story is insufficient.
  elsif p_kind = 'story_draft' then
    select jsonb_build_object('media_url', d.media_url, 'media_transform', d.media_transform,
      'stickers', coalesce((select jsonb_agg(jsonb_build_object('photoUrl', sticker->>'photoUrl'))
        from jsonb_array_elements(case when jsonb_typeof(d.stickers_json) = 'array' then d.stickers_json else '[]'::jsonb end) sticker), '[]'::jsonb))
      into v_document from public.story_drafts d where d.id = p_id;
  elsif p_kind = 'memory_album' then
    select jsonb_agg(jsonb_build_object('story', public.content_media_document('story', s.id), 'media_url', mp.media_url, 'thumbnail_url', mp.thumbnail_url))
      into v_document from public.memory_albums a join public.memory_pages mp on mp.album_id=a.id
      join public.stories s on s.id=mp.story_id and s.user_id=a.user_id where a.id=p_id;
  elsif p_kind = 'highlight' then
    select jsonb_build_object('cover_url', h.cover_url, 'stories', (
      select jsonb_agg(public.content_media_document('story', s.id)) from public.story_highlight_items hi
      join public.stories s on s.id=hi.story_id and s.user_id=h.user_id
      where hi.highlight_id=h.id and public.content_story_audience_visible(s.id)
    )) into v_document from public.story_highlights h where h.id=p_id;
  elsif p_kind = 'sound' then
    select jsonb_build_object('url', s.url) into v_document from public.story_sounds s where s.id = p_id;
  end if;
  return coalesce(v_document, '{}'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.content_media_manifest(p_references jsonb)
 RETURNS TABLE(entity_kind text, entity_id uuid, media_url text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record; use_kind text;
begin
 for r in select * from public.content_media_manifest_before_sound_rights(p_references) loop
  use_kind:=case r.entity_kind when 'post' then 'post' when 'memory_album' then 'memory_album' else 'story' end;
  if exists(select 1 from public.story_sounds s where s.url=r.media_url and not (
   public.sound_rights_allow(s.id,use_kind) or (r.entity_kind='sound' and (public.sound_rights_allow(s.id,'post') or public.sound_rights_allow(s.id,'memory_album')))
  )) then continue; end if;
  entity_kind:=r.entity_kind;entity_id:=r.entity_id;media_url:=r.media_url;return next;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.delete_user_account(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_user_id is distinct from auth.uid()
     and coalesce(auth.jwt()->>'role','') <> 'service_role' then
    raise exception 'You can only delete your own account';
  end if;
  delete from message_deletions where user_id = p_user_id;
  delete from saved_messages where user_id = p_user_id;
  delete from starred_messages where starred_by = p_user_id;
  delete from message_reactions where user_id = p_user_id;
  delete from message_reads where user_id = p_user_id;
  delete from messages where sender_id = p_user_id;
  delete from conversation_typing where user_id = p_user_id;
  delete from conversation_settings where user_id = p_user_id;
  delete from conversation_members where user_id = p_user_id;
  delete from chat_payments where sender_id = p_user_id or recipient_id = p_user_id;
  delete from call_participants where user_id = p_user_id;
  delete from story_views where user_id = p_user_id;
  delete from story_reactions where user_id = p_user_id;
  delete from stories where user_id = p_user_id;
  delete from post_seen where user_id = p_user_id;
  delete from post_bookmarks where user_id = p_user_id;
  delete from post_reposts where user_id = p_user_id;
  delete from post_likes where user_id = p_user_id;
  delete from comment_reactions where user_id = p_user_id;
  delete from post_comments where user_id = p_user_id;
  delete from post_products where post_id in (select id from posts where user_id = p_user_id);
  delete from posts where user_id = p_user_id;
  -- offers made by the person, and offers on the person's own listings
  delete from listing_offers where proposer_id = p_user_id;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'listing_offers' and column_name = 'listing_id') then
    execute 'delete from listing_offers where listing_id in (select id from marketplace_listings where seller_id = $1)' using p_user_id;
  end if;
  delete from marketplace_listings where seller_id = p_user_id;
  delete from saved_listings where user_id = p_user_id;
  delete from seller_reviews where seller_id = p_user_id or reviewer_id = p_user_id;
  -- jobs the person posted, applications they sent, and applications to their jobs
  delete from job_saves where user_id = p_user_id or job_id in (select id from jobs where posted_by = p_user_id);
  delete from job_applications where applicant_id = p_user_id or job_id in (select id from jobs where posted_by = p_user_id);
  delete from jobs where posted_by = p_user_id;
  delete from follows where follower_id = p_user_id or following_id = p_user_id;
  delete from follow_requests where requester_id = p_user_id or target_id = p_user_id;
  delete from close_friends where owner_id = p_user_id or friend_id = p_user_id;
  delete from blocked_users where blocker_id = p_user_id or blocked_id = p_user_id;
  delete from user_reports where reporter_id = p_user_id or reported_id = p_user_id;
  delete from notifications where recipient_id = p_user_id;
  delete from club_members where user_id = p_user_id;
  delete from community_members where user_id = p_user_id;
  delete from business_members where member_id = p_user_id or business_id = p_user_id;
  delete from business_reviews where user_id = p_user_id;
  delete from business_posts where owner_id = p_user_id;
  delete from business_profiles where owner_id = p_user_id or profile_id = p_user_id;
  delete from support_tickets where user_id = p_user_id;
  delete from user_app_settings where user_id = p_user_id;
  delete from user_presence where user_id = p_user_id;
  delete from user_push_tokens where user_id = p_user_id;
  delete from profiles where id = p_user_id;
  delete from auth.users where id = p_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_legacy_chat_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE value text; old_value text; loc text; bucket text; object_name text;
BEGIN
 IF TG_TABLE_NAME='channel_messages' THEN
  value:=NEW.media_url;
  IF TG_OP='UPDATE' THEN old_value:=OLD.media_url; END IF;
 ELSIF TG_TABLE_NAME='conversations' THEN
  value:=NEW.group_avatar_url;
  IF TG_OP='UPDATE' THEN old_value:=OLD.group_avatar_url; END IF;
 ELSE
  value:=NEW.cv_url;
  IF TG_OP='UPDATE' THEN old_value:=OLD.cv_url; END IF;
 END IF;
 IF value IS NULL OR (TG_OP='UPDATE' AND value IS NOT DISTINCT FROM old_value) THEN RETURN NEW; END IF;
 loc:=public.chat_object_path(value);
 IF TG_TABLE_NAME='channel_messages' AND value ~ '/storage/v1/object/public/channel-media/' THEN
   IF value !~ '^https://[^/?#]+/storage/v1/object/public/channel-media/[0-9a-f-]{36}/[0-9a-f-]{36}/[A-Za-z0-9_.-]+$' THEN RAISE EXCEPTION 'Invalid channel attachment'; END IF;
   bucket:='channel-media'; object_name:=substring(value FROM '/storage/v1/object/public/channel-media/(.*)$');
   IF split_part(object_name,'/',1)<>NEW.channel_id::text OR split_part(object_name,'/',2)<>NEW.sender_id::text OR NOT public.can_act_as(NEW.sender_id) THEN
     RAISE EXCEPTION 'Channel attachment must belong to this channel and author' USING ERRCODE='42501';
   END IF;
 ELSIF loc IS NOT NULL THEN
   bucket:=split_part(loc,'/',1); object_name:=substring(loc FROM position('/' IN loc)+1);
   IF TG_TABLE_NAME='channel_messages' THEN
     IF bucket<>'chat-media' OR split_part(object_name,'/',1)<>NEW.sender_id::text OR NOT public.can_act_as(NEW.sender_id) THEN RAISE EXCEPTION 'Invalid channel attachment owner' USING ERRCODE='42501'; END IF;
   ELSIF TG_TABLE_NAME='job_applications' THEN
     IF bucket<>'chat-files' OR split_part(object_name,'/',1)<>NEW.applicant_id::text OR NOT public.can_act_as(NEW.applicant_id) THEN RAISE EXCEPTION 'Invalid CV attachment owner' USING ERRCODE='42501'; END IF;
   ELSIF bucket<>'chat-media' OR NOT public.can_act_as(split_part(object_name,'/',1)::uuid) THEN
     RAISE EXCEPTION 'Group photo must belong to the editor' USING ERRCODE='42501';
   END IF;
 ELSIF value ~ '/storage/v1/object/(public/|sign/|authenticated/)?(chat-media|chat-files|channel-media)/' THEN
   RAISE EXCEPTION 'Invalid private attachment locator' USING ERRCODE='42501';
 ELSE RETURN NEW;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id=bucket AND o.name=object_name) THEN
   RAISE EXCEPTION 'Upload the attachment before sharing it' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.open_legacy_chat_media(p_message_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  viewer uuid := auth.uid();
  attachment_type text;
  claimed_url text;
  claimed_remaining integer;
  grant_row public.chat_media_view_grants%ROWTYPE;
BEGIN
  IF to_regnamespace('private_media') IS NOT NULL
     OR viewer IS NULL
     OR p_message_id IS NULL
     OR p_request_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Reject unsupported attachments before consuming a view. This row lock is
  -- also held by claim_chat_media_view and prevents a delete racing the result.
  SELECT m.media_type
    INTO attachment_type
    FROM public.messages m
   WHERE m.id = p_message_id
     AND m.deleted_at IS NULL
   FOR UPDATE;

  IF attachment_type IS NULL OR attachment_type NOT IN ('image', 'video') THEN
    RETURN NULL;
  END IF;

  -- This existing RPC owns conversation authorization, uploader binding,
  -- sender exclusion, request idempotency, and the shared message_views count.
  SELECT c.url, c.remaining
    INTO claimed_url, claimed_remaining
    FROM public.claim_chat_media_view(p_message_id, p_request_id) c;

  IF claimed_url IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT g.*
    INTO grant_row
    FROM public.chat_media_view_grants g
   WHERE g.user_id = viewer
     AND g.request_id = p_request_id
     AND g.message_id = p_message_id
     AND g.remaining = claimed_remaining
     AND g.expires_at > clock_timestamp();

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Return the original grant deadline: retrying must never renew a capability.
  -- The Edge signer authenticates again, matches the authorized manifest, and
  -- signs only the seconds still remaining before this timestamp.
  RETURN jsonb_build_object(
    'url', claimed_url,
    'remaining', grant_row.remaining,
    'expiresAt', grant_row.expires_at,
    'mediaType', attachment_type,
    'requestId', grant_row.request_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.platinum_upload_path_allowed(p_bucket text, p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare actor text;
begin
 if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then return false; end if;
 if p_bucket not in ('post-media','story-media','media','avatars','market-media') then return false; end if;
 if p_name is null or length(p_name)>1024 or p_name !~ '^[A-Za-z0-9_. /-]+$'
   or p_name ~ '(^|/)\.\.?(/|$)|//' then return false; end if;
 actor:=case when p_bucket='market-media' and split_part(p_name,'/',1)='listings'
   then split_part(p_name,'/',2) else split_part(p_name,'/',1) end;
 if actor !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or position('/' in p_name)=0 then return false; end if;
 return public.can_act_as(actor::uuid);
end $function$
